yakit.AutoInitYakit()

# 社工生成字典V0.5
# 基于实战总结 尽量比较少的字典减少爆破成本
# V0.5 完成对于域名目标的用户名与密码生成
# V0.6 增加密码规则5


# --- 参数 --- #
type = cli.String("type")
target = cli.String("target",cli.setDefault("www.baidu.com"))
ext = cli.String("ext")

WeakUser = ["admin","user","administrator","root","test","Admin","Administrator","root","Test"]
CommonSymbol = ["@","!","#","$","%","."]
WeakPass = [
    "000", "0000", "000000", "001", "002", "003", "004", "005", "006", "007", "008", "009", "0987", "1", "1111", "111111", "12", "123", "1234", "12345", "123456", "1234567", "12345678", "123456789", "147258", "2003", "2004", "2005", "2006", "2007", "2008", "2009", "2010", "2011", "2012", "2013", "2014", "2015", "2016", "2017", "2018", "2019", "2020", "2021", "2022", "321", "4321", "520", "521", "654321", "666", "6666", "666666", "666888", "6688", "777", "7890", "888", "8888", "888888", "qwer", "test","admin",
]
# --- 执行 --- #
userDictFromDomain = func(domain,ext){
    yakit.Info("[!]Start generate user dict for domain...")
    q = str.SplitAndTrim(domain,".")
    // 添加自定义的词组
    q = append(ext,q...)
    //println(str.Join(q,"/"))
    allUser = WeakUser
    baseUser = []
    // 1. 域名分割以及大写生成用户名
    for _,b := range q[:len(q)-1]{
        // 部分过滤
        if b == "www"{
            continue
            }
        //如果出现 - 则分割
        if str.Contains(b, "-"){
            for _,c := range str.SplitAndTrim(b,"-"){
                baseUser = append(baseUser, c)
                allUser = append(allUser, c)
                //首字母大写
                baseUser = append(baseUser,str.Title(c))
                allUser = append(allUser,str.Title(c))
            }
            continue
        }
        //
        baseUser = append(baseUser, b)
        allUser = append(allUser, b)
        //首字母大写
        baseUser = append(baseUser,str.Title(b))
        allUser = append(allUser,str.Title(b))

        }

    // 2.admin + @domain
    allUser = append(allUser,sprintf("admin@%v",str.Join(q[len(q)-2:],".")))
    // 处于爆破成本考虑注释的代码 weakuser + @ + domain
    // for _,w := range WeakUser{
    //     r = sprintf("%v@%v",w,str.Join(q[len(q)-2:],"."))
    //     baseUser = append(baseUser,r)
    // }


    return baseUser,allUser
}



yakit.EnableTable("User-用户字典", ["User"])
outputTable_user = func(user) {
    data = make(map[string]var)
    data["User"] = user
    yakit.TableData("User-用户字典", data)
}

passDictFromDomain = func(user){
    user = append(user,"admin")
    yakit.Info("[!]Start generate password dict for domain...")
    allPass = []
        // 1. 弱口令
    allPass = append(allPass,WeakPass...)
    result = ""
    for _,u := range user{
        for _,w := range WeakPass{
            // 2. 用户名 + 弱口令
            result += u + w + ","

            for _,s := range CommonSymbol{
                // 3. 用户名 + 特殊符号 + 弱口令
                result +=u + s + w + ","
                // 4. 用户名 + 弱口令 + 特殊符号
                result += u + w + s + ","
            }

        }
        for _,s := range CommonSymbol{
            // 5.admin + 特殊符号 + 用户名
            result += "admin" + s + u + ","
        }


    }
    allPass = append(allPass,str.SplitAndTrim(result, ",")...)
    return allPass
}

yakit.EnableTable("Password-密码字典", ["Password"])
outputTable_pass = func(Password) {
    data = make(map[string]var)
    data["Password"] = Password
    yakit.TableData("Password-密码字典", data)
}

# --- 选择 --- #

if (type == "domain"){
    if (target != ""){
        if (ext != ""){
            ext = str.SplitAndTrim(ext, ",")
        }else{
            ext = []
        }
        // 用户名字典生成
        dm = str.ExtractDomain(target)
        baseUser,allUser = userDictFromDomain(dm[0],ext)
        for _,u := range allUser{
            outputTable_user(u)
        }
        // 密码字典生成
        allPass = passDictFromDomain(baseUser)
        for _,p := range allPass{
            outputTable_pass(p)
        }
        yakit.Info("[+]生成用户名%v个 密码%v个 总计应发送请求%v个",len(allUser),len(allPass),len(allUser)*len(allPass))
    }else{
        yakit.Info("Please enter target !")
    }
}




